import assert from 'node:assert/strict';
import { beforeEach, afterEach, test } from 'node:test';
import { register } from 'node:module';
import { createHash, randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createDatabase } from './sqlite-d1.mjs';

const RealDate = Date, realFetch = globalThis.fetch;
let db, instant;
const env = {};
globalThis.__mlekoTestCloudflareEnv = env;
// This audit must never reach a bank, fiscal provider or real messaging service.
globalThis.fetch = async () => { throw new Error('External network is disabled in the functional audit'); };
register(new URL('./cloudflare-loader.mjs', import.meta.url));
const worker = (await import('../dist/server/index.js')).default;
const at = value => { instant = RealDate.parse(value); };
beforeEach(() => {
 Object.keys(env).forEach(key => delete env[key]);
 Object.assign(env, {APP_ENV:'local',APP_ORIGIN:'http://localhost',PAYMENT_MODE:'mock',BADI_MODE:'mock',EMAIL_MODE:'console',WHATSAPP_MODE:'disabled',ADMIN_LEGACY_ACCESS:'true',ADMIN_SECRET:'audit-only',PAYMENT_WEBHOOK_SECRET:'audit-webhook',CRON_SECRET:'audit-cron'});
 at('2026-12-30T10:00:00Z');
 globalThis.Date = class extends RealDate {constructor(...args){super(...(args.length?args:[instant]));}static now(){return instant;}};
 db = createDatabase(); env.DB = db;
 db.raw.exec("UPDATE products SET is_active=1, allow_subscription=1, price_minor=25000, subscription_price_minor=20000; UPDATE settings SET value_json='0' WHERE key IN ('deliveryFeeMinor','freeDeliveryThresholdMinor');");
});
afterEach(() => {db.close();globalThis.Date=RealDate;});
process.on('exit',()=>{globalThis.fetch=realFetch;});
async function api(path, data, {method=data===undefined?'GET':'POST', admin=false, cookie, key=randomUUID(), headers={}}={}) {
 const response=await worker.fetch(new Request('http://localhost'+path,{method,headers:{'content-type':'application/json',Origin:'http://localhost','Idempotency-Key':key,...(admin?{'x-admin-secret':env.ADMIN_SECRET}:{}),...(cookie?{cookie}:{}),...headers},...(method==='GET'||method==='DELETE'?{}:{body:JSON.stringify(data)})}),env,{waitUntil(){},passThroughOnException(){}});
 const text=await response.text();let body;try{body=JSON.parse(text);}catch{body=text;}
 return {status:response.status,body,headers:response.headers};
}
const ok=(result,status=200)=>{assert.equal(result.status,status,JSON.stringify(result.body));return result.body;};
const one=(sql,...args)=>db.raw.prepare(sql).get(...args);
const count=table=>one(`SELECT COUNT(*) n FROM ${table}`).n;
const line=(type='subscription',cadence='weekly',quantity=2)=>({productId:'prod_kravlje_1l',quantity,purchaseType:type,...(type==='subscription'?{cadence}:{})});
const customer=(extra={})=>({email:'audit@example.test',fullName:'Željko Audit',phone:'+381600000000',addressLine1:'Test ulica 1',city:'Beograd',postalCode:'11000',...extra});
const payload=(items=[line()],extra={})=>({items,customer:customer(),paymentMethod:'card',paymentToken:'mock-audit-token',deliveryDate:'2027-01-01',...extra});
const buy=async(items,extra)=>ok(await api('/api/checkout',payload(items,extra)),201);
function cookie(customerId=one('SELECT id FROM customers LIMIT 1').id) {
 const token=randomUUID();db.raw.prepare("INSERT INTO auth_tokens(id,customer_id,email,token_hash,kind,expires_at) VALUES(?,?,?,?,'session','2030-01-01T00:00:00Z')").run(randomUUID(),customerId,'audit@example.test',createHash('sha256').update(token).digest('base64url'));return 'mm_session='+token;
}
const mutate=async(id,action,extra={})=>api('/api/account/subscriptions/'+id,{action,expectedVersion:one('SELECT version FROM subscriptions WHERE id=?',id).version,...extra},{method:'PATCH',cookie:cookie()});
const setting=async(value)=>ok(await api('/api/admin/settings',value,{method:'PATCH',admin:true}));
const product=(extra={})=>({name:'Тест млеко Ž',slug:'audit-product',unitLabel:'6 × 1 L',priceMinor:35000,subscriptionPriceMinor:32000,description:'Opis proizvoda',...extra});
const newProduct=async(extra)=>ok(await api('/api/admin/products',product(extra),{admin:true}),201).product;
const promo=async(extra={})=>ok(await api('/api/admin/promos',{code:'AUDIT10',discountType:'percent',discountValue:10,...extra},{admin:true}),201).promo;
const quote=async(extra={})=>api('/api/cart',{items:[line('one_time','weekly',2)],deliveryDate:'2027-01-01',...extra});
const generate=async(date='2027-01-01')=>ok(await api('/api/admin/deliveries',{action:'generate',date},{admin:true}));
async function deliver(date,status='delivered'){at(date+'T10:00:00Z');const result=await generate(date);for(const order of result.orders)ok(await api('/api/admin/deliveries',{action:'complete',id:order.id,status},{admin:true}));return result;}

for (const [id, field, value, exposed=field] of [
 ['001','name','Novo mleko'],['002','description','Sveže mleko sa farme.'],['003','imageUrl','/images/mleko-i-mleko-logo-mark.png'],['005','subscriptionPriceMinor',31000],['006','unitLabel','500 ml'],['011','priceMinor',29000],['012','compareAtPriceMinor',49000],['125','name','Млеко čćšđž'],['133','sortOrder',0],['134','category','Jogurt'],['135','isFeatured',true],['097','fiscalTaxLabel','Е']
]) test(`Q${id}: catalog persists ${field} through admin API`,async()=>{
 const p=await newProduct();const changed=ok(await api('/api/admin/products/'+p.id,{[field]:value},{admin:true,method:'PATCH'})).product;assert.equal(changed[exposed],value);
 const listed=ok(await api('/api/admin/products',undefined,{admin:true})).products.find(x=>x.id===p.id);assert.equal(listed[exposed],value);
 if(id==='133'){const catalog=ok(await api('/api/products')).products;assert.equal(catalog[0].id,p.id);}
});
test('Q007 Q114: hidden product disappears and cannot be ordered',async()=>{const p=await newProduct();ok(await api('/api/admin/products/'+p.id,{isActive:false},{admin:true,method:'PATCH'}));assert.ok(!ok(await api('/api/products')).products.some(x=>x.id===p.id));ok(await api('/api/products/'+p.slug),404);ok(await quote({items:[{...line(),productId:p.id}]}),409);});
test('Q010 Q115: one-time-only product cannot be subscribed to',async()=>{const p=await newProduct({allowSubscription:false});ok(await quote({items:[{...line(),productId:p.id}]}),409);ok(await quote({items:[{...line('one_time'),productId:p.id}]}));});
for(const slug of ['bad slug','mleko_1','млеко'])test(`Q123: malformed product slug ${slug} is rejected`,async()=>{ok(await api('/api/admin/products',product({slug}),{admin:true}),422);assert.equal(count('products'),4);});
test('Q124: duplicate product slug is rejected without overwriting original',async()=>{const p=await newProduct();ok(await api('/api/admin/products',product(),{admin:true}),409);assert.equal(one('SELECT name FROM products WHERE id=?',p.id).name,p.name);});
test('Q131 Q136: missing photo remains optional and public catalog hides internal costs',async()=>{const p=await newProduct({imageUrl:null,costMinor:999,packagingCostMinor:88});const publicP=ok(await api('/api/products/'+p.slug)).product;assert.equal(publicP.imageUrl,null);for(const key of ['costMinor','packagingCostMinor','badiSku','fiscalTaxLabel'])assert.equal(Object.hasOwn(publicP,key),false);});
for(const imageUrl of ['http://example.test/a.png','javascript:alert(1)'])test(`Q132: unsafe photo scheme ${imageUrl.split(':')[0]} is rejected`,async()=>{ok(await api('/api/admin/products',product({imageUrl}),{admin:true}),422);});
test('Q137: deleting a purchased product archives it and preserves paid delivery',async()=>{const p=await newProduct();await buy([{...line(),productId:p.id}]);const removed=ok(await api('/api/admin/products/'+p.id,undefined,{admin:true,method:'DELETE'}));assert.equal(removed.archived,true);assert.equal(count('order_items'),1);assert.equal((await generate()).preparation[0].product_id,p.id);});
test('Q138 Q092: product changes leave audit entries, with shared rather than personal actor identity',async()=>{const p=await newProduct();ok(await api('/api/admin/products/'+p.id,{name:'Izmena'},{method:'PATCH',admin:true}));const rows=db.raw.prepare('SELECT action,actor_id FROM audit_log WHERE entity_id=?').all(p.id);assert.deepEqual(rows.map(x=>x.action).sort(),['product.created','product.updated']);assert.ok(rows.every(x=>x.actor_id==='local-admin'));});
for(const type of ['percent','fixed'])test(`Q014 Q015: ${type} promo has independently verified exact total`,async()=>{await promo({discountType:type,discountValue:type==='percent'?10:7000});const result=ok(await quote({promoCode:'AUDIT10'}));assert.equal(result.subtotalMinor,50000);assert.equal(result.discountMinor,type==='percent'?5000:7000);assert.equal(result.totalMinor,type==='percent'?45000:43000);});
for(const [id,extra] of [['116',{endsAt:'2026-12-29T00:00:00Z'}],['117',{startsAt:'2026-12-31T00:00:00Z'}],['118',{minimumOrderMinor:50001}],['016',{usageLimit:0}]])test(`Q${id}: ineligible promo cannot discount the cart`,async()=>{await promo(extra);ok(await quote({promoCode:'AUDIT10'}),422);assert.equal(count('orders'),0);});
test('Q019 Q119 Q120: promo combines with catalog sale, normalizes case and never discounts delivery',async()=>{await setting({deliveryFeeMinor:35000});await promo({discountType:'fixed',discountValue:999999});const result=ok(await quote({promoCode:' audit10 '}));assert.equal(result.discountMinor,50000);assert.equal(result.totalMinor,35000);});
test('Q018: initial promo is not silently renewed on the next package',async()=>{await promo();const purchase=await buy(undefined,{promoCode:'AUDIT10'});for(const date of ['2027-01-01','2027-01-08','2027-01-15','2027-01-22'])await deliver(date);ok(await api('/api/jobs/billing',{month:'2027-02'},{admin:true}));const renewed=one('SELECT discount_minor,promo_code,total_minor FROM orders WHERE id != ?',purchase.order.id);assert.equal(renewed.discount_minor,0);assert.equal(renewed.promo_code,null);assert.equal(renewed.total_minor,160000);});
for(let mask=1;mask<8;mask++)test(`Q023 Q024 Q025 Q112: cart combination ${mask} preserves all purchased units`,async()=>{const options=[line('one_time','weekly',1),line('subscription','weekly',2),line('subscription','biweekly',3)];const items=options.filter((_,i)=>mask&(1<<i));const q=ok(await quote({items}));const expected=items.reduce((sum,item)=>sum+(item.purchaseType==='one_time'?25000*item.quantity:20000*item.quantity*(item.cadence==='weekly'?4:2)),0);assert.equal(q.totalMinor,expected);const purchase=await buy(items);assert.equal(purchase.order.totalMinor,expected);assert.equal(count('order_items'),items.length);if(mask>1){assert.equal(count('package_lines'),items.length);for(const date of ['2027-01-01','2027-01-08','2027-01-15','2027-01-22'])await deliver(date);assert.equal(one("SELECT SUM(quantity) n FROM delivery_items di JOIN delivery_orders dor ON dor.id=di.delivery_order_id WHERE dor.status='delivered'").n,items.reduce((sum,item)=>sum+item.quantity*(item.purchaseType==='one_time'?1:item.cadence==='weekly'?4:2),0));}});
test('Q021 Q022 Q101: guest checkout uses RSD and rejects missing mandatory contact fields',async()=>{for(const field of ['email','fullName','phone','addressLine1','city','postalCode']){const input=payload();delete input.customer[field];ok(await api('/api/checkout',input),422);}const order=await buy();assert.equal(order.order.currency,'RSD');assert.equal(count('customers'),1);});
