test('Q148 Q149: free shipping boundary is exact and later fee changes preserve purchased invoice',async()=>{await setting({deliveryFeeMinor:35000,freeDeliveryThresholdMinor:50000});assert.equal(ok(await quote()).deliveryFeeMinor,0);assert.equal(ok(await quote({items:[line('one_time','weekly',1)]})).deliveryFeeMinor,35000);const paid=await buy();await setting({deliveryFeeMinor:99999});assert.equal(one('SELECT total_minor FROM orders WHERE id=?',paid.order.id).total_minor,paid.order.totalMinor);});
