test('Q155 Q156 Q159: completion rejects unprepared and future deliveries, then cannot reverse handover',async()=>{await buy();const future=await generate();ok(await api('/api/admin/deliveries',{action:'complete',id:future.orders[0].id,status:'delivered'},{admin:true}),409);const locked=ok(await api('/api/admin/deliveries',{action:'lock',date:'2027-01-01',force:true},{admin:true}));future.orders=locked.orders;ok(await api('/api/admin/deliveries',{action:'complete',id:future.orders[0].id,status:'delivered'},{admin:true}),409);at('2027-01-01T10:00:00Z');ok(await api('/api/admin/deliveries',{action:'complete',id:future.orders[0].id,status:'delivered'},{admin:true}));ok(await api('/api/admin/deliveries',{action:'complete',id:future.orders[0].id,status:'failed'},{admin:true}),409);});
