for(const [id,bytes,type,status] of [['127',new Uint8Array(2000001),'image/png',422],['129',new TextEncoder().encode('<svg onload="alert(1)"/>'),'image/svg+xml',422],['130',new TextEncoder().encode('<script>alert(1)</script>'),'image/png',422],['128',readFileSync(new URL('../public/images/mleko-i-mleko-logo-mark.png',import.meta.url)),'image/png',201]])test(`Q${id}: uploaded ${type} with ${bytes.length} bytes validates content and size`,async()=>{const form=new FormData();form.append('image',new File([bytes],'audit-image',{type}));const response=await worker.fetch(new Request('http://localhost/api/admin/product-images',{method:'POST',headers:{'x-admin-secret':env.ADMIN_SECRET,Origin:'http://localhost'},body:form}),env,{waitUntil(){},passThroughOnException(){}});assert.equal(response.status,status);if(status===201){const {url}=await response.json();const image=await worker.fetch(new Request('http://localhost'+url),env,{waitUntil(){},passThroughOnException(){}});assert.equal(image.headers.get('content-type'),'image/png');assert.equal(image.headers.get('x-content-type-options'),'nosniff');assert.equal((await image.arrayBuffer()).byteLength,bytes.length);}else assert.equal(count('product_images'),0);});

