test('Q096: reconciled historical units reduce remaining quantity without duplicate charge',async()=>{const p=await buy();db.raw.exec('DELETE FROM package_lines; DELETE FROM subscription_packages;');const item=one('SELECT id FROM order_items');ok(await api('/api/admin/legacy',{orderId:p.order.id,nextDeliveryDate:'2027-01-08',advanceInvoiceNumber:'EXISTING-PFR',advanceTime:'2026-12-30T10:00:00Z',confirmed:true,lines:[{id:item.id,deliveredQuantity:2}]},{admin:true}));assert.equal(one('SELECT imported_delivered_quantity FROM package_lines').imported_delivered_quantity,2);for(const date of ['2027-01-08','2027-01-15','2027-01-22'])await deliver(date);assert.equal(one('SELECT status FROM subscription_packages').status,'completed');assert.equal(count('orders'),1);assert.equal(count('legacy_reconciliations'),1);});
test('Q141: expired reservation blocks handover and can be exchanged for valid inventory',async()=>{ok(await api('/api/admin/products/prod_kravlje_1l',{inventoryEnabled:true},{admin:true,method:'PATCH'}));ok(await api('/api/admin/inventory',{productId:'prod_kravlje_1l',lotNumber:'A',expiresOn:'2027-01-30',quantity:8},{admin:true}),201);const p=await buy();ok(await mutate(p.subscription.id,'pause',{pauseUntil:'2027-02-01'}));ok(await api('/api/admin/inventory',{productId:'prod_kravlje_1l',lotNumber:'B',expiresOn:'2027-05-01',quantity:8},{admin:true}),201);at('2027-02-05T10:00:00Z');const locked=(await generate('2027-02-05')).orders[0];ok(await api('/api/admin/deliveries',{action:'complete',id:locked.id,status:'delivered'},{admin:true}),409);ok(await api('/api/admin/inventory',{action:'replace',orderId:p.order.id},{admin:true}),201);assert.equal(one("SELECT reserved FROM inventory_lots WHERE lot_number='A'").reserved,0);assert.equal(one("SELECT reserved FROM inventory_lots WHERE lot_number='B'").reserved,8);await deliver('2027-02-05');assert.equal(one("SELECT quantity FROM inventory_lots WHERE lot_number='B'").quantity,6);});
test('Q069: account refund preview is scoped and contains no payment tokens',async()=>{const p=await buy();const result=ok(await api('/api/account/refunds?orderId='+p.order.id,undefined,{cookie:cookie()}));assert.deepEqual(Object.keys(result.order),['id']);await buy(undefined,{customer:customer({email:'different@example.test'})});const other=one("SELECT id FROM customers WHERE email='different@example.test'");ok(await api('/api/account/refunds?orderId='+p.order.id,undefined,{cookie:cookie(other.id)}),404);});
for(const quantity of [1,2,100])for(const cadence of ['weekly','biweekly'])for(const failFirst of [false,true])test(`Q060 Q190: conserved units quantity=${quantity} cadence=${cadence} initialFailure=${failFirst}`,async()=>{const paid=await buy([line('subscription',cadence,quantity)]);const required=quantity*(cadence==='weekly'?4:2);let handed=0,visits=0;let date='2027-01-01';while(handed<required&&visits<10){at(date+'T10:00:00Z');const route=await generate(date);assert.equal(route.orders.length,1);const d=route.orders[0];assert.equal(d.items[0].quantity,Math.min(quantity,required-handed));const fail=failFirst&&visits===0;const amount=fail?0:visits===(failFirst?1:0)&&quantity>1?quantity-1:Number(d.items[0].quantity);ok(await api('/api/admin/deliveries',{action:'complete',id:d.id,status:fail?'failed':'delivered',...(fail?{}:{items:[{id:d.items[0].id,deliveredQuantity:amount}]})},{admin:true}));handed+=amount;visits++;date=new RealDate(RealDate.parse(date+'T12:00:00Z')+(cadence==='weekly'?7:14)*86400000).toISOString().slice(0,10);assert.equal(one('SELECT status FROM subscription_packages WHERE order_id=?',paid.order.id).status,handed===required?'completed':'open');}assert.equal(handed,required);assert.equal(one("SELECT SUM(delivered_quantity) n FROM delivery_items").n,required);assert.equal(one("SELECT COUNT(*) n FROM outbox WHERE topic='fiscal.final.requested'").n,1);});
